"""ABLE Streamlit demo, generated by the 수정본2 notebook.

Session-only calendar/todos. No automatic email sending.
"""
import calendar
import io
import json
import os
import re
import smtplib
from datetime import date, datetime, timedelta
from email.message import EmailMessage
from email.utils import parseaddr
from uuid import uuid4

import streamlit as st
from openai import OpenAI
from PIL import Image, ImageDraw, ImageFont

st.set_page_config(page_title="에이블 AI 개인비서", page_icon="🤖", layout="wide")
st.title("🤖 에이블 | AI 개인비서")
st.caption("회의록 요약 · 캘린더 · To-do List · 음성 명령 · 이메일")

ROLE = """당신은 김 대리의 AI 개인비서 '에이블'입니다. 한국어로 정확하고 친절하게 답하세요.
회의 기록의 사실만 사용하고 없는 담당자·기한·회의 내용을 꾸며내지 마세요.
회의 전체 요약 및 김 대리 업무를 구분해 전달하세요. 업무가 없으면 없다고 말하세요.
사용자가 명시적으로 요청하지 않는 한 이메일 발송을 제안하거나 실행하지 마세요.
"""
MODEL = "gpt-4o-mini"


def init():
    defaults = {
        "events": [], "todos": [], "done_dates": set(),
        "month": date.today().replace(day=1), "selected_day": date.today(),
        "meeting_text": "", "meeting_name": "", "meeting_result": None,
        "recommendations": [], "pending_action": None,
        "email_draft": None, "messages": [], "last_answer": "", "last_transcript": "",
    }
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value


def get_client():
    return OpenAI()


def llm_json(instructions, prompt):
    result = get_client().responses.create(
        model=MODEL,
        instructions=instructions,
        input=prompt,
        text={"format": {"type": "json_object"}},
    )
    return json.loads(result.output_text)


def analyze_meeting(text):
    prompt = f"""아래 회의록만 근거로 분석하여 다음 JSON 객체로만 답하세요.
{{"summary":"전체 회의 요약", "decisions":["결정사항"],
 "kim_tasks":[{{"task":"김 대리 업무", "deadline":"YYYY-MM-DD 또는 빈 문자열", "person":"관련자"}}],
 "events":[{{"title":"마감 일정", "date":"YYYY-MM-DD"}}],
 "todos":["실행할 업무 추천"]}}
events에는 회의에 정확한 날짜가 명시된 마감 업무만 넣고, 애매한 날짜는 제외하세요.
todos는 회의 수행을 위한 할 일을 짧게 제안하세요. 날짜와 업무를 임의로 확정하지 마세요.
[회의록]\n{text}"""
    return llm_json(ROLE, prompt)


def extract_action(request):
    today = date.today().isoformat()
    prompt = f"""사용자 요청을 분석하세요. 오늘 날짜는 {today} (Asia/Seoul 기준 날짜는 앱 서버와 다를 수 있으므로
상대적 날짜가 애매하면 등록하지 말고 질문하세요).
다음 JSON 객체로만 답하세요:
{{"action":"event|todo|question", "title":"업무명", "date":"YYYY-MM-DD 또는 빈 문자열",
"repeat":"매일|매주|반복 없음", "end_date":"YYYY-MM-DD 또는 빈 문자열", "answer":"질문이 필요한 경우 설명"}}
캘린더 일정은 명확한 날짜가 있어야 하며, 반복할 일은 todo로 분류하세요.
명확하지 않은 항목을 추측하지 말고 question으로 반환하세요.
[사용자 요청]\n{request}"""
    return llm_json(ROLE, prompt)


def ask_ai(message, meeting):
    history = st.session_state.messages[-6:]
    conversation = [{"role": "system", "content": ROLE}]
    conversation += history
    content = message + (f"\n\n[회의록]\n{meeting}" if meeting else "")
    conversation.append({"role": "user", "content": content})
    result = get_client().responses.create(model=MODEL, input=conversation)
    answer = result.output_text
    st.session_state.messages.extend([
        {"role": "user", "content": message},
        {"role": "assistant", "content": answer},
    ])
    return answer


def transcribe(audio_bytes):
    f = io.BytesIO(audio_bytes)
    f.name = "recording.wav"
    return get_client().audio.transcriptions.create(model="gpt-4o-mini-transcribe", file=f).text


def voice_bytes(text):
    return get_client().audio.speech.create(
        model="gpt-4o-mini-tts", voice="nova", input=text,
        response_format="mp3"
    ).content


def send_email(to, subject, body):
    sender = os.getenv("GMAIL_ADDRESS")
    password = os.getenv("GMAIL_APP_PASSWORD")
    address = parseaddr(to)[1]
    if not sender or not password:
        return "Gmail 발신 정보가 Secrets에 없습니다."
    if not address or address != to.strip() or "@" not in address:
        return "받는 사람 이메일 주소를 확인해 주세요."
    msg = EmailMessage()
    msg["From"], msg["To"], msg["Subject"] = sender, address, subject
    msg.set_content(body)
    try:
        with smtplib.SMTP("smtp.gmail.com", 587, timeout=20) as smtp:
            smtp.starttls()
            smtp.login(sender, password)
            smtp.send_message(msg)
        return None
    except Exception as exc:
        return str(exc)


def add_event(title, day, project="일반"):
    st.session_state.events.append({
        "id": uuid4().hex, "title": title.strip(), "day": day, "project": project
    })


def add_todo(title, repeat="반복 없음", start=None, end=None):
    start = start or date.today()
    end = end or start
    st.session_state.todos.append({
        "id": uuid4().hex, "title": title.strip(), "repeat": repeat,
        "start": start, "end": end
    })


def due_on(todo, day):
    if day < todo["start"] or day > todo["end"]:
        return False
    if todo["repeat"] == "매일":
        return True
    if todo["repeat"] == "매주":
        return day.weekday() == todo["start"].weekday()
    return day == todo["start"]


def font(size=22):
    candidates = [
        "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
        "/usr/share/fonts/truetype/noto/NotoSansCJK-Regular.ttc",
        "/usr/share/fonts/truetype/nanum/NanumGothic.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
    ]
    for name in candidates:
        if os.path.exists(name):
            return ImageFont.truetype(name, size)
    return ImageFont.load_default()


def png_export(lines, title):
    row_h = 42
    img = Image.new("RGB", (1050, max(220, 130 + row_h * len(lines))), "white")
    draw = ImageDraw.Draw(img)
    draw.rounded_rectangle((20, 20, 1030, img.height - 20), radius=18, outline="#d0d7e2", width=2)
    draw.text((48, 45), title, font=font(30), fill="#172554")
    for i, line in enumerate(lines):
        draw.text((48, 110 + i * row_h), str(line)[:75], font=font(19), fill="#334155")
    output = io.BytesIO()
    img.save(output, format="PNG")
    return output.getvalue()


def display_calendar():
    st.subheader("📅 캘린더")
    a, b, c = st.columns([1, 5, 1])
    if a.button("◀", key="cal_prev"):
        m = st.session_state.month
        st.session_state.month = (m - timedelta(days=1)).replace(day=1)
        st.rerun()
    month = st.session_state.month
    b.markdown(f"### {month.year}년 {month.month}월")
    if c.button("▶", key="cal_next"):
        st.session_state.month = (month.replace(day=28) + timedelta(days=4)).replace(day=1)
        st.rerun()
    columns = st.columns(7)
    for col, title in zip(columns, ["월", "화", "수", "목", "금", "토", "일"]):
        col.markdown(f"**{title}**")
    for week in calendar.monthcalendar(month.year, month.month):
        columns = st.columns(7)
        for col, num in zip(columns, week):
            if num == 0:
                col.write(" ")
                continue
            day = date(month.year, month.month, num)
            items = [x for x in st.session_state.events if x["day"] == day]
            with col.container(border=True):
                if st.button(str(num), key=f"calendar_{day}", use_container_width=True):
                    st.session_state.selected_day = day
                    st.rerun()
                for event in items[:3]:
                    st.caption(f"📌 {event['title'][:14]}")
                if len(items) > 3:
                    st.caption(f"외 {len(items)-3}개")

    selected = st.session_state.selected_day
    st.markdown(f"#### 📆 {selected} 상세 일정")
    selected_events = [e for e in st.session_state.events if e["day"] == selected]
    if not selected_events:
        st.info("이 날짜에 등록된 일정이 없습니다.")
    for event in selected_events:
        c1, c2 = st.columns([5, 1])
        c1.write(f"📌 [{event['project']}] {event['title']}")
        if c2.button("삭제", key=f"ev_del_{event['id']}"):
            st.session_state.events = [e for e in st.session_state.events if e["id"] != event["id"]]
            st.rerun()

    with st.form("new_event"):
        title = st.text_input("새 일정", placeholder="최종 보고서 제출")
        day = st.date_input("마감 날짜", value=selected)
        project = st.selectbox("구분", ["일반", "프로젝트 A", "프로젝트 B", "개인"])
        submitted = st.form_submit_button("일정 등록")
    if submitted:
        if title.strip():
            add_event(title, day, project)
            recommendations = []
            if "회의" in title:
                recommendations = ["회의 안건 정리", "회의 자료 준비", "참석자 확인"]
            elif "발표" in title:
                recommendations = ["발표 자료 제작", "발표 대본 작성", "발표 리허설"]
            elif "보고서" in title:
                recommendations = ["자료 조사", "보고서 초안 작성", "최종 검토"]
            else:
                recommendations = [f"{title} 준비사항 확인"]
            st.session_state.recommendations = [{"id":uuid4().hex,"title":x,"day":day} for x in recommendations]
            st.rerun()
        st.warning("일정명을 입력해 주세요.")

    if st.session_state.recommendations:
        st.markdown("#### 💡 일정 관련 추천 To-do")
        for rec in st.session_state.recommendations:
            c1, c2 = st.columns([5,1])
            c1.write(f"• {rec['title']}")
            if c2.button("추가", key=f"rec_{rec['id']}"):
                add_todo(rec["title"], start=rec["day"])
                st.session_state.recommendations = [r for r in st.session_state.recommendations if r["id"] != rec["id"]]
                st.rerun()

    lines = [f"{x['day']} | {x['project']} | {x['title']}" for x in sorted(st.session_state.events, key=lambda x:x['day'])]
    st.download_button("📥 캘린더 PNG 저장", png_export(lines,"ABLE Calendar"),
                       file_name="calendar.png", mime="image/png")


def display_todos():
    st.subheader("✅ 나의 To-do List")
    with st.form("new_todo"):
        title = st.text_input("할 일", placeholder="매일 코테 1시간 공부")
        repeat = st.selectbox("반복 주기", ["매일", "매주", "반복 없음"])
        start = st.date_input("시작일", value=date.today(), key="todo_start")
        end = st.date_input("종료일", value=date.today()+timedelta(days=7), key="todo_end")
        submit = st.form_submit_button("To-do 등록")
    if submit:
        if not title.strip():
            st.warning("할 일을 입력해 주세요.")
        elif end < start:
            st.warning("종료일이 시작일보다 빠를 수 없습니다.")
        else:
            add_todo(title, repeat, start, end)
            st.rerun()

    selected = st.date_input("조회 날짜", value=date.today(), key="todo_date")
    due = [x for x in st.session_state.todos if due_on(x, selected)]
    count = 0
    for task in due:
        key = (task['id'], selected.isoformat())
        checked = key in st.session_state.done_dates
        c1, c2 = st.columns([5, 1])
        current = c1.checkbox(task['title'], value=checked, key=f"todo_check_{task['id']}_{selected}")
        if current:
            st.session_state.done_dates.add(key)
            count += 1
        else:
            st.session_state.done_dates.discard(key)
        if c2.button("삭제", key=f"todo_del_{task['id']}"):
            st.session_state.todos = [t for t in st.session_state.todos if t['id'] != task['id']]
            st.rerun()
    if not due:
        st.info("해당 날짜에 할 일이 없습니다.")
    else:
        st.progress(count/len(due), text=f"완료 {count}/{len(due)}")
    lines = [f"{'[완료]' if (t['id'],selected.isoformat()) in st.session_state.done_dates else '[미완료]'} {t['title']}" for t in due]
    st.download_button("📥 To-do PNG 저장", png_export(lines,f"ABLE To-do {selected}"),
                       file_name="todo.png", mime="image/png")


def meeting_section():
    st.subheader("📄 회의록 분석")
    uploaded = st.file_uploader("회의록 TXT 업로드", type=["txt"])
    if uploaded is not None:
        try:
            text = uploaded.getvalue().decode("utf-8-sig")
            if text != st.session_state.meeting_text:
                st.session_state.meeting_text = text
                st.session_state.meeting_name = uploaded.name
                st.session_state.meeting_result = None
        except UnicodeDecodeError:
            st.error("UTF-8 형식의 TXT 파일을 올려 주세요.")
    if st.button("🔍 회의록 분석 실행", disabled=not bool(st.session_state.meeting_text)):
        try:
            with st.spinner("회의록을 분석하고 있습니다..."):
                st.session_state.meeting_result = analyze_meeting(st.session_state.meeting_text)
        except Exception as exc:
            st.error(f"회의록 분석 오류: {exc}")
    result = st.session_state.meeting_result
    if not result:
        return
    st.markdown("#### 전체 회의 요약")
    st.write(result.get("summary", ""))
    if result.get("decisions"):
        st.markdown("#### 주요 결정 사항")
        for decision in result["decisions"]:
            st.write(f"• {decision}")
    st.markdown("#### 김 대리 담당 업무")
    if not result.get("kim_tasks"):
        st.info("김 대리에게 배정된 업무가 없습니다.")
    for task in result.get("kim_tasks", []):
        st.write(f"• {task.get('task','')} | 기한: {task.get('deadline') or '미정'} | 관련자: {task.get('person') or '미정'}")

    st.markdown("#### 📅 회의록에서 추출한 마감 일정 후보")
    for i, item in enumerate(result.get("events", [])):
        c1, c2 = st.columns([5,1])
        c1.write(f"{item.get('date','')} · {item.get('title','')}")
        if c2.button("등록", key=f"meeting_ev_{i}"):
            try:
                add_event(item["title"], date.fromisoformat(item["date"]))
                st.success("캘린더에 등록했어요.")
            except (ValueError, KeyError):
                st.warning("날짜 형식을 확인해 주세요.")
    st.markdown("#### 💡 추천 To-do")
    for i, title in enumerate(result.get("todos", [])):
        c1, c2 = st.columns([5,1])
        c1.write(f"• {title}")
        if c2.button("추가", key=f"meeting_todo_{i}"):
            add_todo(title, start=date.today())
            st.success("To-do에 추가했어요.")


def command_section():
    st.subheader("🎤 에이블에게 요청")
    mode = st.radio("입력 방식", ["텍스트", "음성"], horizontal=True)
    typed = st.text_area("텍스트 명령 또는 질문", placeholder="11월 10일까지 보고서 제출을 캘린더에 등록해 줘", key="cmd_text") if mode == "텍스트" else ""
    recorded = st.audio_input("음성 명령 녹음") if mode == "음성" else None
    c1, c2 = st.columns(2)
    register = c1.button("📌 일정·To-do 등록 요청", use_container_width=True)
    ask = c2.button("💬 일반 질문", use_container_width=True)
    if register or ask:
        try:
            question = typed
            if mode == "음성":
                if recorded is None:
                    st.warning("먼저 음성을 녹음해 주세요.")
                    return
                with st.spinner("음성을 텍스트로 변환 중..."):
                    question = transcribe(recorded.getvalue())
                st.session_state.last_transcript = question
            if not question.strip():
                st.warning("요청 내용을 입력해 주세요.")
                return
            if register:
                with st.spinner("등록 내용을 분석 중..."):
                    st.session_state.pending_action = extract_action(question)
            else:
                with st.spinner("답변 생성 중..."):
                    st.session_state.last_answer = ask_ai(question, st.session_state.meeting_text)
        except Exception as exc:
            st.error(f"요청 처리 오류: {exc}")
    if st.session_state.last_transcript:
        st.info(f"음성 인식 결과: {st.session_state.last_transcript}")
    pending = st.session_state.pending_action
    if pending:
        st.markdown("#### 등록 전 확인")
        st.json(pending)
        action = pending.get("action")
        if action == "question":
            st.warning(pending.get("answer") or "날짜나 반복 조건을 좀 더 구체적으로 알려 주세요.")
        else:
            if st.button("✅ 위 내용으로 등록"):
                try:
                    title = pending["title"].strip()
                    if not title:
                        raise ValueError("업무명이 없습니다.")
                    if action == "event":
                        add_event(title, date.fromisoformat(pending["date"]))
                    elif action == "todo":
                        start = date.fromisoformat(pending["date"]) if pending.get("date") else date.today()
                        end = date.fromisoformat(pending["end_date"]) if pending.get("end_date") else start
                        if end < start:
                            raise ValueError("종료일이 시작일보다 빠릅니다.")
                        add_todo(title, pending.get("repeat", "반복 없음"), start, end)
                    else:
                        raise ValueError("지원하지 않는 등록 유형입니다.")
                    st.session_state.pending_action = None
                    st.success("등록했습니다.")
                    st.rerun()
                except (ValueError, KeyError) as exc:
                    st.error(f"등록할 정보를 확인해 주세요: {exc}")
        if st.button("등록 취소"):
            st.session_state.pending_action = None
            st.rerun()
    if st.session_state.last_answer:
        st.markdown("#### 에이블 답변")
        st.write(st.session_state.last_answer)
        if st.button("🔊 음성으로 듣기"):
            try:
                with st.spinner("음성 생성 중..."):
                    st.audio(voice_bytes(st.session_state.last_answer), format="audio/mp3")
            except Exception as exc:
                st.error(f"음성 생성 실패: {exc}")


def email_section():
    with st.expander("✉️ 요약 결과 이메일로 보내기 (확인 후 발송)"):
        summary = st.session_state.meeting_result
        body = ""
        if summary:
            body = summary.get("summary", "") + "\n\n김 대리 업무\n" + "\n".join(
                f"- {x.get('task','')} (기한: {x.get('deadline') or '미정'})"
                for x in summary.get("kim_tasks", [])
            )
        with st.form("email_form"):
            to = st.text_input("수신자 이메일")
            subject = st.text_input("제목", value="에이블 미팅 요약")
            body_input = st.text_area("이메일 본문", value=body, height=180)
            submit = st.form_submit_button("확인 후 이메일 발송")
        if submit:
            error = send_email(to, subject, body_input)
            if error:
                st.error(f"이메일 발송 실패: {error}")
            else:
                st.success("메일 서버에 발송 요청이 전달되었습니다. 받은편지함을 확인해 주세요.")


init()
left, right = st.columns([2.1, 1.15], gap="large")
with left:
    display_calendar()
    st.divider()
    meeting_section()
with right:
    display_todos()

st.divider()
